// Inlined watercolor artwork (data URIs) so illustrations work in the single-file build.

export const ARTWORK: Record<string, string> = {
  "hero": 'data:image/jpeg;base64,',
  "przyroda": 'data:image/jpeg;base64,',
  "zwierzeta": 'data:image/jpeg;base64,',
  "pojazdy": 'data:image/jpeg;base64,',
  "kreatywne": 'data:image/jpeg;base64,',
  "nauka": 'data:image/jpeg;base64,',
  "zabawa": 'data:image/jpeg;base64,',
  "featured-akwarium": 'data:image/jpeg;base64,',
  "featured-rakieta": 'data:image/jpeg;base64,',
  "featured-pizza": 'data:image/jpeg;base64,',
};

export function artUrl(key: string): string {
  return ARTWORK[key] || ARTWORK.przyroda;
}

export const CATEGORY_ARTWORK: Record<string, string> = {
  przyroda: ARTWORK.przyroda,
  zwierzeta: ARTWORK.zwierzeta,
  pojazdy: ARTWORK.pojazdy,
  kreatywne: ARTWORK.kreatywne,
  nauka: ARTWORK.nauka,
  zabawa: ARTWORK.zabawa,
};

export const FEATURED_ARTWORK: Record<string, string> = {
  akwarium: ARTWORK['featured-akwarium'],
  rakieta: ARTWORK['featured-rakieta'],
  pizza: ARTWORK['featured-pizza'],
};
